import pytest
from candidate import below_zero


class TestBelowZero:
    def test_all_positive_operations_returns_false(self):
        assert below_zero([1, 2, 3]) == False

    def test_operations_going_below_zero_returns_true(self):
        assert below_zero([1, 2, -4, 5]) == True

    def test_single_negative_operation_returns_true(self):
        assert below_zero([-1]) == True

    def test_single_positive_operation_returns_false(self):
        assert below_zero([5]) == False

    def test_single_zero_operation_returns_false(self):
        assert below_zero([0]) == False

    def test_empty_list_returns_false(self):
        assert below_zero([]) == False

    def test_balance_reaches_exactly_zero_returns_false(self):
        assert below_zero([5, -5]) == False

    def test_balance_goes_below_zero_at_end_returns_true(self):
        assert below_zero([3, -5]) == True

    def test_balance_goes_below_zero_in_middle_returns_true(self):
        assert below_zero([10, -15, 20]) == True

    def test_large_positive_then_large_negative_returns_true(self):
        assert below_zero([1000000, -2000000]) == True

    def test_large_positive_then_small_negative_returns_false(self):
        assert below_zero([1000000, -500000]) == False

    def test_all_zeros_returns_false(self):
        assert below_zero([0, 0, 0]) == False

    def test_mixed_operations_never_below_zero_returns_false(self):
        assert below_zero([3, -1, 2, -4, 5]) == False

    def test_first_operation_negative_returns_true(self):
        assert below_zero([-10, 5, 20]) == True

    def test_last_operation_makes_balance_negative_returns_true(self):
        assert below_zero([5, 3, -10]) == True

    def test_oscillating_balance_stays_above_zero_returns_false(self):
        assert below_zero([1, -1, 1, -1, 1]) == False

    def test_large_number_of_operations_returns_false(self):
        ops = [1] * 100
        assert below_zero(ops) == False

    def test_large_number_of_operations_going_negative_returns_true(self):
        ops = [1] * 50 + [-100]
        assert below_zero(ops) == True

    def test_single_element_large_negative_returns_true(self):
        assert below_zero([-999999999]) == True

    def test_operations_with_floats_still_works(self):
        assert below_zero([1.5, 2.5, -5.0]) == True

    def test_operations_with_floats_stays_above_zero(self):
        assert below_zero([1.5, 2.5, -3.0]) == False

    def test_none_input_raises_type_error(self):
        with pytest.raises(TypeError):
            below_zero(None)

    def test_string_input_raises_type_error(self):
        with pytest.raises(TypeError):
            below_zero("hello")

    def test_integer_input_raises_type_error(self):
        with pytest.raises(TypeError):
            below_zero(42)

    def test_list_with_string_elements_raises_type_error(self):
        with pytest.raises(TypeError):
            below_zero(["a", "b"])

    def test_tuple_input_raises_type_error(self):
        with pytest.raises(TypeError):
            below_zero((1, 2, -5))

    def test_balance_stays_at_zero_throughout_returns_false(self):
        assert below_zero([1, -1, 1, -1]) == False

    def test_negative_then_positive_still_returns_true(self):
        assert below_zero([-1, 100]) == True

    def test_zero_then_negative_returns_true(self):
        assert below_zero([0, -1]) == True

    def test_positive_then_zero_then_negative_returns_true(self):
        assert below_zero([5, -5, -1]) == True

    def test_positive_then_zero_stays_zero_returns_false(self):
        assert below_zero([5, -5, 0]) == False

    def test_repeated_same_negative_value_returns_true(self):
        assert below_zero([-1, -1, -1]) == True

    def test_repeated_same_positive_value_returns_false(self):
        assert below_zero([1, 1, 1]) == True if False else below_zero([1, 1, 1]) == False

    def test_alternating_positive_negative_stays_non_negative(self):
        assert below_zero([2, -1, 2, -1, 2, -1]) == False

    def test_alternating_positive_negative_goes_negative(self):
        assert below_zero([1, -2, 3, -5]) == True
